// 原承包人可核对自己携信与亲自交付记录；接信按钮总按当前真实Known会面再报价。
#include "task_personal_message_view.hpp"
#include "task_personal_message_detail.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;
BoundaryValue identity(const WorldIdentity& id){StableId world;const char* hex="0123456789abcdef";for(auto byte:id.world_id){world.push_back(hex[byte>>4]);world.push_back(hex[byte&15]);}return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{id.execution_epoch}},{"revision",V{id.revision}},{"tick",V{id.tick}}});}
}
Outcome<BoundaryValue> query_task_personal_messages(const TaskPersonalMessageSources& x,const InteractionState& interaction,const InteractionAccess& access,Integer cursor){if(x.phase)return {false,{},common_failure("TaskPersonalMessageStableQueryRequired").error};const auto& actor=x.common.state().metadata.player_actor_id;if(!x.common.actor(actor))return {false,{},common_failure("UnknownPlayer").error};auto valid=validate_task_personal_messages(x);if(!valid.ok)return {false,{},valid.error};std::vector<const TaskRecord*> known;for(auto i=x.tasks.tasks.rows().rbegin();i!=x.tasks.tasks.rows().rend();++i)if(i->second.assignee==actor&&task_personal_message_policy(x.catalog,i->second.offer_id))known.push_back(&i->second);if(cursor<0||static_cast<std::size_t>(cursor)>known.size())return {false,{},common_failure("InvalidTaskPersonalMessageCursor").error};V::Array rows;Integer next=cursor;
 for(;static_cast<std::size_t>(next)<known.size()&&rows.size()<16;++next){const auto& task=*known[static_cast<std::size_t>(next)];const auto& original=*x.task_catalog.offers.find(task.offer_id);StableId stage="carrying",text="原信件待亲自送达",fact,place;Integer observed=task.accepted_tick;const TaskPersonalMessageStart* start=nullptr;for(const auto& r:x.state.starts.rows())if(r.second.task_id==task.id)start=&r.second;if(start){fact=start->fact_id;observed=start->started_tick;place=start->recipient_declaration.declaration.meeting.context.place_id;const auto* end=personal_message_detail::end_for_start(x.state,start->fact_id);stage=end?(end->success?"delivered":"interrupted"):"delivering";text=end?(end->success?"已亲手交付原信件，待向发信人返报":"接信未完成，原信件仍按原委托办理"):"正在当面交付原信件";if(end){fact=end->fact_id;observed=end->tick;}}
  for(const auto& r:x.handoffs.receipts.rows())if(r.second.task_id==task.id){stage="delivered";text="已亲手交付原信件，待向发信人返报";fact=r.first;observed=r.second.tick;place=r.second.place_id;}
  for(const auto& r:x.handoffs.reports.rows())if(r.second.task_id==task.id){stage="reported";text="已向原发信人当面返报";fact=r.first;observed=r.second.tick;place=r.second.place_id;}
  // 只检查本人的原办理容器；不借全World任务产权扫描暴露远处的批次和现位置。
  if(stage=="carrying"){const auto* person=x.common.actor(actor);const auto* bag=person?x.common.inventory(person->inventory_id):nullptr;bool carrying=false;if(bag)for(const auto& lot:bag->lots)if(lot.item_id==original.goal.message_id&&lot.quantity==1&&owner_equal(lot.owner,Owner{Owner::Kind::task,task.id,{}}))carrying=true;if(!carrying)text="本人携带物中未见原任务信件";}
  if(task.status=="cancelled"||task.status=="failed"){stage="closed";text="原委托已终结";}else if(task.status=="accepting"){stage="accepting";text="正在受领原委托";}
  V::Array actions;if(task.status=="active"&&(stage=="carrying"||stage=="interrupted")){auto quote=preview_task_personal_message(x,interaction,access,actor,{task.id});actions.push_back(boundary::obj({{"command",V{StableId{task_personal_message_command}}},{"params",boundary::obj({{"task_id",V{task.id}}})},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}},{"text",V{StableId{"按收件本人声明交信"}}},{"summary",V{StableId{"占用双方一半日；原收件人须在这次私人会面中明确接信，完成时仍在场。"}}}}));}
  rows.push_back(boundary::obj({{"id",V{task.id}},{"task_id",V{task.id}},{"display_name",V{original.display_name}},{"recipient_actor_id",V{original.goal.receiver_actor}},{"stage",V{stage}},{"status_text",V{text}},{"source_fact_id",V{fact}},{"known_place_id",V{place}},{"observed_tick",V{observed}},{"terms_text",V{StableId{"原报酬："+std::to_string(original.reward)+"（返报后结算）；原截止：第"+std::to_string(task.deadline_tick)+"半日。只交原信件，办理需半日。历史会面地点不表示对方现在仍在那里。"}}},{"actions",V{std::move(actions)}}}));
 }
 V::Dict page{{"ok",V{true}},{"enabled",V{true}},{"source_identity",identity(x.common.state().identity)},{"observer_actor_id",V{actor}},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(static_cast<std::size_t>(next)<known.size())page.emplace_back("next_cursor",V{next});return {true,V{std::move(page)},{}};
}
}
